1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's locality (region code). It is the REGION segment embedded at the
9	 * start of the owner's {@code memberId}, which is {@link #region(Owner)}.
10	 */
11	public class Locality {
12	
13	    private static final Map<String, String> CITY_REGION = Map.of(
14	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
15	
16	    public static String locality(Owner owner) {
17	        return region(owner);
18	    }
19	
20	    /**
21	     * Region code derived from the postcode: a four-digit postcode inside a known range
22	     * wins (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); otherwise it falls back to the
23	     * city-to-region table, which disambiguates cities that share a name.
24	     */
25	    public static String region(Owner owner) {
26	        String byPostcode = byPostcode(owner.getPostcode());
27	        return byPostcode != null ? byPostcode : CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
28	    }
29	
30	    private static String byPostcode(String postcode) {
31	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
32	            return null;
33	        }
34	        int p = Integer.parseInt(postcode);
35	        if (p >= 2000 && p <= 2099) return "NSW";
36	        if (p >= 3000 && p <= 3099) return "VIC";
37	        if (p >= 4000 && p <= 4099) return "QLD";
38	        return null;
39	    }
40	}
