1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * Maps an owner's locality/region code to its IANA timezone name via a fixed table
7	 * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). Any
8	 * other region has no known timezone.
9	 */
10	public class Timezone {
11	
12	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
13	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
14	
15	    public static String of(String region) {
16	        return REGION_TIMEZONE.get(region);
17	    }
18	}
