1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Set;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's segment as {@code <TIER>_<AREA>}: TIER is {@code PREMIUM} at
9	 * membershipLevel 3 or more else {@code STANDARD}; AREA is {@code METRO} when the owner's
10	 * locality is a known region (NSW, VIC or QLD) else {@code REGIONAL}.
11	 */
12	public final class OwnerSegment {
13	
14	    private static final Set<String> METRO = Set.of("NSW", "VIC", "QLD");
15	
16	    private OwnerSegment() {
17	    }
18	
19	    public static String of(int membershipLevel, Owner owner) {
20	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
21	        String area = METRO.contains(Locality.locality(owner)) ? "METRO" : "REGIONAL";
22	        return tier + "_" + area;
23	    }
24	}
