1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.mapper.OwnerMapper;
10	import org.springframework.samples.petclinic.model.Owner;
11	
12	/**
13	 * Emits an immutable structured {@code OWNER_CREATED} event to the {@code AUDIT} logger
14	 * once the owner has been saved. The event carries a monotonically increasing {@code seq}
15	 * across creates, the owner id, its membership level and its current primary identifier
16	 * (the customerCode today; whatever unifies it later, e.g. the memberId). Keeping the
17	 * identifier read in {@link #identifier(Owner)} means only that one line moves when the
18	 * primary identifier changes.
19	 */
20	public class AuditOwnerCreatedEvent {
21	
22	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
23	
24	    private static final AtomicLong SEQ = new AtomicLong();
25	
26	    public void service(@Val Owner owner, OwnerMapper ownerMapper) {
27	        long seq = SEQ.incrementAndGet();
28	        int membershipLevel = ownerMapper.toOwnerDto(owner).getMembershipLevel();
29	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"memberId\":\"{}\",\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
30	            seq, owner.getId(), identifier(owner), membershipLevel);
31	    }
32	
33	    /** The owner's primary identifier, the unified memberId. */
34	    private static String identifier(Owner owner) {
35	        return owner.getCustomerCode();
36	    }
37	}
