50	    @Mapping(target = "ageBand", expression = "java(owner.getBirthDate() == null ? null : org.springframework.samples.petclinic.rest.function.owner.AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()))")
51	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.rest.function.owner.CheckUniqueIdentity.identityKey(owner))")
52	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneDisplay.display(owner.getTelephone()))")
53	    @Mapping(target = "riskFlag", expression = "java(org.springframework.samples.petclinic.rest.function.owner.RiskFlag.of(owner, ownerRepository))")
54	    public abstract OwnerDto toOwnerDto(Owner owner);
55	
