1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the owner's unified {@code memberId} before {@link SaveOwner} runs, formatted
12	 * {@code <REGION><FY><HASH8><CHK>}: the region code derived from the postcode, the
13	 * 2-digit fiscal year of the registration date, the first eight upper-case hex
14	 * characters of SHA-256 over the telephone followed by the last name, and a single Luhn
15	 * check digit over the preceding digits. It depends only on the owner.
16	 */
17	public class AssignCustomerCode {
18	
19	    public void service(@Val Owner owner) {
20	        String base = Locality.region(owner)
21	                + String.format("%02d", FiscalYear.endYear(owner.getRegistrationDate()) % 100)
22	                + hash8(blank(owner.getTelephone()) + blank(owner.getLastName()));
23	        owner.setCustomerCode(base + CheckDigit.checkDigit(base));
24	    }
25	
26	    private static String hash8(String input) {
27	        try {
28	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
29	            StringBuilder sb = new StringBuilder(16);
30	            for (int i = 0; i < 4; i++) {
31	                sb.append(String.format("%02X", digest[i]));
32	            }
33	            return sb.toString();
34	        }
35	        catch (NoSuchAlgorithmException ex) {
36	            throw new IllegalStateException(ex);
37	        }
38	    }
39	
40	    private static String blank(String value) {
41	        return value == null ? "" : value;
42	    }
43	}
