3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
11	
12	/**
13	 * Rejects a create whose whole {@code identityKey} already belongs to another owner,
14	 * before {@link SaveOwner} runs. Consolidates the former telephone, email and household
15	 * duplicate checks: only an exact full-key match is a duplicate, so two members of the
16	 * same household with different telephones are both allowed. Handled with 409 by
17	 * {@code DuplicateIdentityHandler}. Runs after {@link AssignHouseholdId} so the key can
18	 * include the household part.
19	 */
20	public class CheckUniqueIdentity {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
23	            throws DuplicateIdentityException {
24	        String key = identityKey(owner);
25	        for (Owner other : ownerRepository.findAll()) {
26	            if (!other.isDeleted() && !other.getId().equals(owner.getId())
27	                    && key.equals(identityKey(other))) {
28	                throw new DuplicateIdentityException(key);
29	            }
30	        }
31	    }
32	
33	    /** SHA-256 hex over normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName). */
34	    public static String identityKey(Owner owner) {
35	        String raw = normalizeTelephone(owner.getTelephone()) + "|" + lower(owner.getEmail())
36	                + "|" + Soundex.code(owner.getLastName());
37	        return sha256Hex(raw);
38	    }
39	
40	    private static String normalizeTelephone(String telephone) {
41	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
42	    }
43	
44	    private static String lower(String value) {
45	        return value == null ? "" : value.toLowerCase();
46	    }
47	
48	    private static String sha256Hex(String value) {
49	        try {
50	            byte[] digest = MessageDigest.getInstance("SHA-256")
51	                    .digest(value.getBytes(StandardCharsets.UTF_8));
52	            StringBuilder sb = new StringBuilder(64);
53	            for (byte b : digest) {
54	                sb.append(String.format("%02x", b));
55	            }
56	            return sb.toString();
57	        }
58	        catch (NoSuchAlgorithmException e) {
59	            throw new IllegalStateException(e);
60	        }
61	    }
62	}
