3	/**
4	 * American Soundex code of a surname: the first letter followed by up to three digits,
5	 * zero-padded to four characters. Used as the name component of the owner identity key
6	 * and to group phonetically similar surnames for soft-duplicate detection.
7	 */
8	public final class Soundex {
9	
10	    private Soundex() {
11	    }
12	
13	    /** Soundex of {@code name} (e.g. "Robert" -> "R163"); "0000" when it has no letters. */
14	    public static String code(String name) {
15	        String s = name == null ? "" : name.toUpperCase().replaceAll("[^A-Z]", "");
16	        if (s.isEmpty()) {
17	            return "0000";
18	        }
19	        StringBuilder sb = new StringBuilder().append(s.charAt(0));
20	        int prev = digit(s.charAt(0));
21	        for (int i = 1; i < s.length() && sb.length() < 4; i++) {
22	            char c = s.charAt(i);
23	            int d = digit(c);
24	            if (d != 0 && d != prev) {
25	                sb.append(d);
26	            }
27	            if (c != 'H' && c != 'W') {
28	                prev = d; // H and W are transparent: they do not reset the previous code
29	            }
30	        }
31	        while (sb.length() < 4) {
32	            sb.append('0');
33	        }
34	        return sb.toString();
35	    }
36	
37	    /** Soundex digit for a letter; 0 for vowels and the transparent H/W. */
38	    private static int digit(char c) {
39	        switch (c) {
40	            case 'B': case 'F': case 'P': case 'V':
41	                return 1;
42	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
43	                return 2;
44	            case 'D': case 'T':
45	                return 3;
46	            case 'L':
47	                return 4;
48	            case 'M': case 'N':
49	                return 5;
50	            case 'R':
51	                return 6;
52	            default:
53	                return 0;
54	        }
55	    }
56	}
