3	/**
4	 * Computes the single Luhn check digit (0-9) over the digits contained in a value. The
5	 * rightmost digit is doubled, alternating leftwards; each doubled value above nine has
6	 * nine subtracted, and the digit that makes the running sum a multiple of ten is
7	 * returned. Used for the {@code CHK} segment of the memberId.
8	 */
9	public class CheckDigit {
10	
11	    public static int checkDigit(String value) {
12	        int sum = 0;
13	        boolean dbl = true;
14	        for (int i = value.length() - 1; i >= 0; i--) {
15	            char c = value.charAt(i);
16	            if (c < '0' || c > '9') {
17	                continue;
18	            }
19	            int d = c - '0';
20	            if (dbl) {
21	                d *= 2;
22	                if (d > 9) {
23	                    d -= 9;
24	                }
25	            }
26	            sum += d;
27	            dbl = !dbl;
28	        }
29	        return (10 - (sum % 10)) % 10;
30	    }
31	}
