package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

public final class MembershipLevel {
    private MembershipLevel() {}

    public static int points(Owner owner, OwnerRepository ownerRepository) {
        int points = 0;
        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) points += 2;
        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) points += 1;
        if (HouseholdTier.isGold(owner, ownerRepository)) points += 2;
        if (tenureFiscalYears(owner) > 1) points += 3;
        return points;
    }

    public static int level(int points) {
        if (points >= 6) return 4;
        if (points >= 4) return 3;
        if (points >= 2) return 2;
        return 1;
    }

    private static int tenureFiscalYears(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        return registrationDate == null ? 0 : FiscalYear.elapsed(registrationDate, LocalDate.now());
    }
}
