`/home/daniel/sandbox/src/main/java/org/springframework/samples/petclinic/rest/function/owner/CheckUniqueHousehold.java` (provides `normalize` used by AssignHouseholdId; enforces household uniqueness):
```java
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

public class CheckUniqueHousehold {

    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(sharesHousehold)) {
            return;
        }
        String householdId = owner.getHouseholdId();
        for (Owner other : ownerRepository.findAll()) {
            if (!other.isDeleted() && !other.getId().equals(owner.getId())
                    && householdId.equals(other.getHouseholdId())) {
                throw new DuplicateHouseholdException(owner.getLastName(), owner.getPostcode());
            }
        }
    }

    static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
