      title: Owner
      description: A pet owner.
      allOf:
        - $ref: '#/components/schemas/OwnerFields'
        - type: object
          properties:
            id: { type: integer, format: int32, readOnly: true }
            selfLink: { type: string, example: '/api/owners/1', readOnly: true }
            displayName: { type: string, example: 'Franklin, George', readOnly: true }
            salutation: { type: string, example: 'DR Who', readOnly: true }
            initials: { type: string, example: 'G.F.', readOnly: true }
            telephoneDisplay: { type: string, example: '+61 412 345 678', readOnly: true }
            memberId:
              description: "Unified member identifier '<REGION><FY><HASH8><CHK>': the region code, the 2-digit fiscal year of the registration date, the first eight upper-case hex characters of SHA-256 over telephone + lastName, and a single Luhn check digit over the digits of the preceding segments."
              type: string
              example: 'NSW263F5A1B9C4'
              readOnly: true
            fiscalYear: { type: string, example: 'FY26', readOnly: true }
            householdId:
