    @Mapping(target = "registrationDate", expression = "java(ownerDto.getRegistrationDate() != null ? ownerDto.getRegistrationDate() : java.time.LocalDate.now())")
    public abstract Owner toOwner(OwnerFieldsDto ownerDto);

